<?php
require __DIR__.'/../app/bootstrap.php';$adminId=require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$userId=(int)($_POST['user_id']??0);$role=(string)($_POST['role']??'user');if(!in_array($role,['user','assessor','admin'],true))throw new InvalidArgumentException('Invalid role.');if($userId===$adminId && $role!=='admin')throw new InvalidArgumentException('You cannot remove your own administrator role from this screen.');$pdo->prepare('UPDATE user_auth SET role=? WHERE user_id=?')->execute([$role,$userId]);flash('success','User role updated.');redirect('admin/users.php');}catch(Throwable $e){flash('error',$e->getMessage());redirect('admin/users.php');}}
$sampleSelect=db_column_exists('users','is_sample')?',u.is_sample':'';$users=$pdo->query('SELECT u.id,u.email,u.display_name,u.created_at,u.last_active_at,ua.role'.$sampleSelect.' FROM users u JOIN user_auth ua ON ua.user_id=u.id ORDER BY u.created_at DESC LIMIT 250')->fetchAll();$success=flash('success');$error=flash('error');$title='Users — Vacation Brain';require __DIR__.'/../partials/header.php';
?>
<section class="dashboard"><div class="shell"><div class="dashboard-head"><div><div class="eyebrow">Admin · Users</div><h1>Users</h1><p class="muted">Review Vacation Brain accounts and manage User, Qualified Assessor, and Admin access.</p></div><a class="button secondary small" href="<?=e(app_url('admin/index.php'))?>">Admin home</a></div><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="dashboard-card"><div class="table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Joined</th><th>Last active</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['display_name']?:'—')?></strong><?php if(!empty($u['is_sample'])):?><br><span class="sample-badge">Sample profile</span><?php endif;?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['created_at'])?></td><td><?=e($u['last_active_at']?:'—')?></td><td><form method="post" class="inline-role"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><select name="role"><option value="user" <?=$u['role']==='user'?'selected':''?>>User</option><option value="assessor" <?=$u['role']==='assessor'?'selected':''?>>Qualified Assessor</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Admin</option></select><button class="button secondary small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><p class="microcopy">“Qualified Assessor” is an internal Vacation Brain travel-preference assessment role only. It does not represent a healthcare credential.</p></div></div></section><?php require __DIR__.'/../partials/footer.php';?>
